# 《阿毘達磨俱舍論》異譯對讀 —— 由 scripts/tripitaka_compare.py 以其全域 exec（SETS 可直接用）。
#
# 骨架＝梵本頌號（Pradhan 1975 本的品.頌，GRETIL 兩檔一致：頌本 `sa_vasubandhu-abhidharmakoza`、
# 自釋 `sa_vasubandhu-abhidharmakozabhASya`，皆以 VAkK_品.頌 標頌）；一頌一節、釋文隨頌（照中論 madhyamaka）。
# 五欄：梵本頌、梵本自釋、玄奘《俱舍論本頌》T1560、玄奘《俱舍論》T1558、真諦《俱舍釋論》T1559。
# 切法：
#   梵本頌：頌首行起（各品首頌從品題起）。
#   梵本自釋：頌 n 起於 VAkK_(n-1) 之後第一個含粗體（頌文）的段落；前一段若是短問句（kim／katham／…āha）併入。
#   T1560：頌首行起；玄奘偈頌與梵本頌界偶差半頌（切在行中第二 pāda）。
#   T1558：該頌首句；若是「頌曰」區塊第一行，回推到「頌曰」前那一句提問（照中論把「問曰」併入該頌）；
#          一個頌曰區塊含數頌時在區塊中按頌切，論曰釋文因此落在區塊末頌。
#   T1559：真諦逐句引偈（「偈曰：…」），以該頌第一個偈句為界（同段偈曰前的提問句、或前一段短問句併入）。
# 切點由 session 暫存的產生器（T1560 行號表＋真諦／玄奘字重疊 NW 對齊）算出最短唯一起頭字，再逐頌人工核。


def _ak(slug, k, a, b, units, vers):
    heads = {"T1558": ["分別界品第一", "分別根品第二之一", "分別世品第三之一", "分別業品第四之一", "分別隨眠品第五之一",
                       "分別賢聖品第六之一", "分別智品第七之一", "分別定品第八之一", "破執我品第九之一"],
             "T1559": ["釋論中分別界品第一", "俱舍釋論中分別根品第二之一", "釋論中分別世間品第三", "中分別業品第四",
                       "中分別惑品第五", "分別聖道果人品第六之一", "分別慧品第七之一", "分別三摩跋提品第八", "破說我品第九"],
             "T1560": ["分別界品第一（四十四頌）", "分別根品第二（七十四頌）", "分別世界品第三（九十九頌）", "分別業品第四（一百三十一頌）",
                       "分別隨眠品第五（六十九頌）", "分別賢聖品第六（八十三頌）", "分別智品第七（六十一頌）", "分別定品第八（三十九頌）"]}
    meta = {"sa": ("梵本頌", "《阿毘達磨俱舍論本頌》Abhidharmakośakārikā・GRETIL（參 Pradhan 1975、Gokhale 1946）"),
            "sab": ("梵本自釋", "《阿毘達磨俱舍論》Abhidharmakośabhāṣya・GRETIL（Pradhan 1975，Hackett／Lusthaus 校）"),
            "T1560": ("玄奘頌本", "玄奘譯《阿毘達磨俱舍論本頌》・唐"),
            "T1558": ("玄奘論本", "玄奘譯《阿毘達磨俱舍論》・唐 651–654 年"),
            "T1559": ("真諦釋論", "真諦譯《阿毘達磨俱舍釋論》・陳 563–567 年")}
    pin = _AK_PIN[k - 1]
    versions = []
    for w, (start, end, cuts) in vers.items():
        lab, who = meta[w]
        if w == "sa":
            src = {"gretil": "sa_vasubandhu-abhidharmakoza", "start": start}
        elif w == "sab":
            src = {"gretil": "sa_vasubandhu-abhidharmakozabhASya", "start": start}
        else:
            src = {"work": w, "nodes": [heads[w][k - 1]], "start": start, "anchor_nodes": []}
        if end:
            src["end"] = end
        versions.append({"id": "sa-bhasya" if w == "sab" else w, "lang": "sa" if w in ("sa", "sab") else "lzh",
                         "label": lab, "who": who, "src": src, "cuts": cuts})
    SETS[slug] = {
        "title": f"俱舍論・{pin}（{k}.{a}–{k}.{b}）", "family": "sa", "extra_works": [],
        "intro": (f"《阿毘達磨俱舍論》第{'一二三四五六七八九'[k - 1]}品〈{pin}〉頌 {k}.{a}–{k}.{b}，一頌一節（頌號依 Pradhan 本，GRETIL 標 VAkK_品.頌）。"
                  "五欄：梵本頌、梵本自釋（bhāṣya）、玄奘《俱舍論本頌》、玄奘《俱舍論》、真諦《俱舍釋論》；論本欄自該頌（含引出該頌的提問句）起、到下一頌前的釋文止。"
                  "玄奘《俱舍論》常把數頌合為一個「頌曰」再一併解釋，區塊中按頌切開，釋文因此都落在區塊末頌；真諦本逐句引偈、隨句解釋，與梵本自釋的節奏相近。"
                  "稱友 Yaśomitra《明了義釋》Sphuṭārthā 是自釋的疏，不收。" + _AK_NOTE.get(slug, "")),
        "units": units, "versions": versions}


